"""The contract between all three lanes. Freeze this before 10:15.

Lane B (checkpoints) produces a `Claim`. Lane A (graph) produces `ChangedSymbol`
and `Reach` values. The core turns those into a `Report`. Lane C renders it.
Nobody imports anybody else's module — they all import this one.

This is a leaf module: it depends on nothing in the package, so `graph.py` and
`core.py` can both import it without a cycle.
"""

from __future__ import annotations

import json
from dataclasses import asdict, dataclass, field
from datetime import datetime, timezone
from enum import StrEnum
from typing import Any, Self

SCHEMA_VERSION = 1


# ---------------------------------------------------------------------------
# vocabulary
# ---------------------------------------------------------------------------


class SymbolKind(StrEnum):
    FUNCTION = "function"
    METHOD = "method"
    TYPE = "type"
    ROUTE = "route"
    FILE = "file"
    SYMBOL = "symbol"  # graph gave us something we don't have a bucket for


class EdgeKind(StrEnum):
    CALL = "call"
    TYPE_CONSUMER = "type-consumer"
    DATA_FLOW = "data-flow"
    CO_CHANGE = "co-change"
    ROUTE = "route"
    UNKNOWN = "unknown"


class ChangeKind(StrEnum):
    ADDED = "added"
    MODIFIED = "modified"
    REMOVED = "removed"
    MOVED = "moved"


class ClaimSource(StrEnum):
    """How we learned what the agent said it did. Ordered by trustworthiness."""

    FILES_TOUCHED = "files-touched"  # structural, always available
    SUMMARY = "summary"  # symbols named in the agent's own summary
    TRANSCRIPT = "transcript"  # symbols named anywhere in the session
    STRUCTURAL = "structural"  # degraded: files only, no symbol resolution


class GraphMode(StrEnum):
    """What the graph could actually tell us. Drives the honesty of the report."""

    SEMANTIC = "semantic"  # calls and types resolved
    INVENTORY = "inventory"  # files and symbol structure only, no call analysis
    SNAPSHOT = "snapshot"  # served from an exported graph, no working tree
    UNAVAILABLE = "unavailable"  # no graph at all; findings are file-level


# ---------------------------------------------------------------------------
# values
# ---------------------------------------------------------------------------


@dataclass(frozen=True, slots=True, order=True)
class SymbolRef:
    """A node in the graph, with the jump target that makes a finding evidence."""

    file: str
    line: int
    name: str
    id: str = ""
    kind: SymbolKind = SymbolKind.SYMBOL

    def __post_init__(self) -> None:
        if not self.id:
            # Stable identity when the graph doesn't hand us one.
            object.__setattr__(self, "id", f"{self.file}:{self.line}:{self.name}")

    @property
    def location(self) -> str:
        return f"{self.file}:{self.line}"

    def __str__(self) -> str:
        return f"{self.name} ({self.location})"


@dataclass(frozen=True, slots=True)
class ChangedSymbol:
    symbol: SymbolRef
    change: ChangeKind = ChangeKind.MODIFIED


@dataclass(frozen=True, slots=True)
class Reach:
    """A symbol the change can reach, and the evidence for why we say so."""

    symbol: SymbolRef
    distance: int
    origin: SymbolRef | None = None  # nearest changed symbol
    edge_kinds: tuple[EdgeKind, ...] = ()
    via: tuple[SymbolRef, ...] = ()  # shortest path, origin -> symbol
    covering_tests: tuple[SymbolRef, ...] = ()

    @property
    def untested(self) -> bool:
        return not self.covering_tests

    @property
    def is_public_surface(self) -> bool:
        return self.symbol.kind is SymbolKind.ROUTE

    def explain(self) -> str:
        """One line a reviewer can act on."""
        if self.via:
            trail = " -> ".join(s.name for s in self.via)
        elif self.origin:
            trail = f"{self.origin.name} -> {self.symbol.name}"
        else:
            trail = self.symbol.name
        tests = "no test coverage" if self.untested else f"{len(self.covering_tests)} test(s)"
        return f"{self.symbol.location}  {trail}  [{self.distance} hop(s), {tests}]"


@dataclass(frozen=True, slots=True)
class Overclaim:
    """Something the agent described that the graph cannot see."""

    name: str
    why: str = "not present in the graph"


@dataclass(frozen=True, slots=True)
class Claim:
    """Lane B's output: what the agent said it did."""

    summary: str = ""
    symbols: tuple[SymbolRef, ...] = ()
    files: tuple[str, ...] = ()
    unresolved: tuple[str, ...] = ()  # names we couldn't map to graph symbols
    sources: tuple[ClaimSource, ...] = ()

    @property
    def symbol_ids(self) -> frozenset[str]:
        return frozenset(s.id for s in self.symbols)


@dataclass(frozen=True, slots=True)
class Stats:
    changed_symbols: int = 0
    reached_symbols: int = 0
    untested_reach: int = 0
    max_distance: int = 0
    graph_queries: int = 0
    cache_hits: int = 0
    elapsed_ms: int = 0
    truncated: bool = False  # hit depth_cap or max_symbols_per_query


# ---------------------------------------------------------------------------
# the report
# ---------------------------------------------------------------------------


@dataclass(slots=True)
class Report:
    """Claim vs. reality for one checkpoint.

    The three buckets are a set difference over symbol ids:

        confirmed = claimed  &  reachable
        silent    = reachable - claimed      <- the finding that wins the demo
        overclaim = claimed  - reachable
    """

    checkpoint_id: str
    repo: str
    graph_mode: GraphMode
    claim: Claim = field(default_factory=Claim)
    commit_sha: str | None = None
    generated_at: datetime = field(default_factory=lambda: datetime.now(timezone.utc))

    changed: tuple[ChangedSymbol, ...] = ()
    confirmed: tuple[Reach, ...] = ()
    silent: tuple[Reach, ...] = ()
    overclaim: tuple[Overclaim, ...] = ()

    test_command: str | None = None
    degraded_reason: str | None = None
    stats: Stats = field(default_factory=Stats)
    schema_version: int = SCHEMA_VERSION

    # --- derived ----------------------------------------------------------

    @property
    def all_reach(self) -> tuple[Reach, ...]:
        return self.confirmed + self.silent

    @property
    def untested_reach(self) -> tuple[Reach, ...]:
        """The most actionable line in the report: reachable, and nothing covers it."""
        return tuple(r for r in self.all_reach if r.untested)

    @property
    def public_surface(self) -> tuple[Reach, ...]:
        return tuple(r for r in self.all_reach if r.is_public_surface)

    @property
    def is_clean(self) -> bool:
        return not self.silent and not self.overclaim

    @property
    def is_degraded(self) -> bool:
        return self.graph_mode in (GraphMode.INVENTORY, GraphMode.UNAVAILABLE)

    def headline(self) -> str:
        """One sentence. Every renderer opens with this, so they can't disagree."""
        if self.is_degraded:
            return (
                f"{self.graph_mode.value} graph only — "
                f"{len(self.changed)} changed symbol(s), reach not resolved"
            )
        if self.is_clean:
            return f"{len(self.confirmed)} reachable symbol(s), all accounted for"
        parts = [f"{len(self.silent)} symbol(s) reachable but unmentioned"]
        if untested := len(self.untested_reach):
            parts.append(f"{untested} with no test coverage")
        if public := len(self.public_surface):
            parts.append(f"{public} on public surface")
        if self.overclaim:
            parts.append(f"{len(self.overclaim)} claim(s) the graph can't see")
        return ", ".join(parts)

    def exit_code(self, threshold: int | None = None) -> int:
        """CI renderer. 0 clean, 1 findings, 2 could not analyse."""
        if self.graph_mode is GraphMode.UNAVAILABLE:
            return 2
        limit = 1 if threshold is None else threshold
        if len(self.untested_reach) >= limit or self.silent:
            return 1
        return 0

    def ranked_silent(self) -> tuple[Reach, ...]:
        """Untested first, then public surface, then nearest. Renderers don't re-sort."""
        return tuple(
            sorted(
                self.silent,
                key=lambda r: (not r.untested, not r.is_public_surface, r.distance),
            )
        )

    # --- serialization ----------------------------------------------------

    def to_dict(self) -> dict[str, Any]:
        data = asdict(self)
        data["generated_at"] = self.generated_at.isoformat()
        return data

    def to_json(self, *, indent: int | None = 2) -> str:
        return json.dumps(self.to_dict(), indent=indent, default=str)

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> Self:
        """Round-trips the committed fixture, so renderers develop without a graph."""
        sym = lambda d: SymbolRef(**{**d, "kind": SymbolKind(d.get("kind", "symbol"))})  # noqa: E731

        def reach(d: dict[str, Any]) -> Reach:
            return Reach(
                symbol=sym(d["symbol"]),
                distance=d["distance"],
                origin=sym(d["origin"]) if d.get("origin") else None,
                edge_kinds=tuple(EdgeKind(e) for e in d.get("edge_kinds", ())),
                via=tuple(sym(s) for s in d.get("via", ())),
                covering_tests=tuple(sym(s) for s in d.get("covering_tests", ())),
            )

        claim_raw = data.get("claim") or {}
        return cls(
            checkpoint_id=data["checkpoint_id"],
            repo=data["repo"],
            graph_mode=GraphMode(data["graph_mode"]),
            claim=Claim(
                summary=claim_raw.get("summary", ""),
                symbols=tuple(sym(s) for s in claim_raw.get("symbols", ())),
                files=tuple(claim_raw.get("files", ())),
                unresolved=tuple(claim_raw.get("unresolved", ())),
                sources=tuple(ClaimSource(s) for s in claim_raw.get("sources", ())),
            ),
            commit_sha=data.get("commit_sha"),
            generated_at=datetime.fromisoformat(data["generated_at"]),
            changed=tuple(
                ChangedSymbol(sym(c["symbol"]), ChangeKind(c.get("change", "modified")))
                for c in data.get("changed", ())
            ),
            confirmed=tuple(reach(r) for r in data.get("confirmed", ())),
            silent=tuple(reach(r) for r in data.get("silent", ())),
            overclaim=tuple(Overclaim(**o) for o in data.get("overclaim", ())),
            test_command=data.get("test_command"),
            degraded_reason=data.get("degraded_reason"),
            stats=Stats(**data.get("stats", {})),
            schema_version=data.get("schema_version", SCHEMA_VERSION),
        )


@dataclass(slots=True)
class ReportSet:
    """Pre-absorbs the "analyse the whole branch" curveball.

    Renderers take `ReportSet`; a single-checkpoint run is a set of one. Doing
    this now costs ten lines and saves an interface change at 13:00.
    """

    reports: tuple[Report, ...] = ()

    def __iter__(self):
        return iter(self.reports)

    def __len__(self) -> int:
        return len(self.reports)

    @classmethod
    def of(cls, *reports: Report) -> Self:
        return cls(tuple(reports))

    @property
    def stats(self) -> Stats:
        return Stats(
            changed_symbols=sum(len(r.changed) for r in self.reports),
            reached_symbols=sum(len(r.all_reach) for r in self.reports),
            untested_reach=sum(len(r.untested_reach) for r in self.reports),
            max_distance=max((r.stats.max_distance for r in self.reports), default=0),
            graph_queries=sum(r.stats.graph_queries for r in self.reports),
            cache_hits=sum(r.stats.cache_hits for r in self.reports),
            elapsed_ms=sum(r.stats.elapsed_ms for r in self.reports),
            truncated=any(r.stats.truncated for r in self.reports),
        )

    def headline(self) -> str:
        if len(self.reports) == 1:
            return self.reports[0].headline()
        flagged = sum(1 for r in self.reports if not r.is_clean)
        return f"{flagged} of {len(self.reports)} checkpoint(s) have unmentioned reach"

    def exit_code(self, threshold: int | None = None) -> int:
        return max((r.exit_code(threshold) for r in self.reports), default=0)

    def to_json(self, *, indent: int | None = 2) -> str:
        payload = {
            "schema_version": SCHEMA_VERSION,
            "headline": self.headline(),
            "stats": asdict(self.stats),
            "reports": [r.to_dict() for r in self.reports],
        }
        return json.dumps(payload, indent=indent, default=str)


# ---------------------------------------------------------------------------
# fixture
# ---------------------------------------------------------------------------


def sample_report() -> Report:
    """The demo case, hand-written.

    Commit this as JSON at 10:15. Lane C builds every renderer against it while
    lanes A and B are still shelling out to anything, and it is the offline
    fallback if the venue wifi dies during the demo.
    """
    mw = SymbolRef("app/auth/middleware.py", 41, "verify_token", kind=SymbolKind.FUNCTION)
    dep = SymbolRef("app/api/deps.py", 18, "current_user", kind=SymbolKind.FUNCTION)
    route = SymbolRef("app/api/routes/billing.py", 92, "POST /billing/charge", kind=SymbolKind.ROUTE)
    svc = SymbolRef("app/services/billing_service.py", 55, "charge_customer", kind=SymbolKind.METHOD)
    test = SymbolRef("tests/unit/test_deps.py", 12, "test_current_user", kind=SymbolKind.FUNCTION)

    return Report(
        checkpoint_id="REDACTED",
        repo="entireio/demo-app",
        commit_sha="4f1c9ae",
        graph_mode=GraphMode.SEMANTIC,
        claim=Claim(
            summary="Refactored the auth middleware. Nothing else affected.",
            symbols=(mw,),
            files=("app/auth/middleware.py",),
            unresolved=("TokenCache",),
            sources=(ClaimSource.FILES_TOUCHED, ClaimSource.SUMMARY),
        ),
        changed=(ChangedSymbol(mw, ChangeKind.MODIFIED),),
        confirmed=(Reach(dep, 1, origin=mw, edge_kinds=(EdgeKind.CALL,), covering_tests=(test,)),),
        silent=(
            Reach(route, 3, origin=mw, edge_kinds=(EdgeKind.CALL, EdgeKind.ROUTE), via=(mw, dep, route)),
            Reach(svc, 2, origin=mw, edge_kinds=(EdgeKind.CALL,), via=(mw, dep, svc)),
        ),
        overclaim=(Overclaim("TokenCache", "no symbol of that name in the graph"),),
        test_command="pytest tests/unit/test_deps.py",
        stats=Stats(
            changed_symbols=1, reached_symbols=3, untested_reach=2,
            max_distance=3, graph_queries=4, elapsed_ms=820,
        ),
    )


if __name__ == "__main__":  # sanity check the contract, no tooling required
    report = sample_report()
    assert Report.from_dict(json.loads(report.to_json())).headline() == report.headline()
    print(report.headline())
    for reach in report.ranked_silent():
        print("  ", reach.explain())

"""The seam the Noon Curveball is most likely to land on.

`GraphProvider` is the only way the core learns anything about the codebase.
Three implementations ship:

    EntireGraphProvider    shells out to `entire graph ... --json`   (default)
    SnapshotGraphProvider  reads an `entire graph snapshot` export   (no worktree)
    DegradedGraphProvider  git-only, file-level reach                (no graph)

Swapping one for another is a one-line change in `select_provider`. Nothing in
the core knows which one it has.

WARNING — every `_parse_*` function below is written against the documented
shape of `entire graph --json`, not against output anyone has seen. Pin them at
09:15 by running each command once and pasting the real JSON into the fixtures.
The tolerant key lookup buys us a wrong-guess or two; it is not a substitute.
"""

from __future__ import annotations

import json
import subprocess
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Iterable, Protocol, runtime_checkable

from .config import Config
from .report import (
    ChangedSymbol,
    ChangeKind,
    EdgeKind,
    GraphMode,
    Reach,
    SymbolKind,
    SymbolRef,
)


class GraphError(RuntimeError):
    """The graph was asked something it could not answer."""


class GraphUnavailable(GraphError):
    """No usable graph at all. Callers should fall back, not crash."""


@dataclass(frozen=True, slots=True)
class Capabilities:
    mode: GraphMode
    languages: frozenset[str] = frozenset()
    raw: dict[str, Any] | None = None

    @property
    def semantic(self) -> bool:
        return self.mode is GraphMode.SEMANTIC

    def covers(self, path: str) -> bool:
        suffix = Path(path).suffix.lstrip(".")
        return not self.languages or suffix in self.languages


# ---------------------------------------------------------------------------
# the interface
# ---------------------------------------------------------------------------


@runtime_checkable
class GraphProvider(Protocol):
    """Six questions. Anything the core needs is one of these."""

    mode: GraphMode

    def capabilities(self) -> Capabilities:
        """What can this graph actually resolve? Call before trusting reach."""

    def changed_symbols(self) -> list[ChangedSymbol]:
        """Symbols touched in the working tree (or HEAD), not a line diff."""

    def impact(self, symbol: SymbolRef, *, depth: int) -> list[Reach]:
        """Downstream blast radius of one symbol."""

    def neighbors(self, symbol: SymbolRef) -> list[Reach]:
        """One hop: callers, type consumers, routes."""

    def symbols(self, *, path_prefix: str | None = None) -> list[SymbolRef]:
        """The symbol table. Used to resolve claimed names and to find tests."""

    def define(self, name: str) -> SymbolRef | None:
        """Resolve a bare name from the agent's summary to a real symbol."""

    def query_stats(self) -> tuple[int, int]:
        """(queries issued, cache hits) — folded into Report.stats."""


# ---------------------------------------------------------------------------
# tolerant parsing
# ---------------------------------------------------------------------------


def _first(raw: dict[str, Any], *keys: str, default: Any = None) -> Any:
    for key in keys:
        if key in raw and raw[key] is not None:
            return raw[key]
    return default


def _items(payload: Any, *keys: str) -> list[dict[str, Any]]:
    """Accept either a bare list or an object wrapping one."""
    if isinstance(payload, list):
        return [item for item in payload if isinstance(item, dict)]
    if isinstance(payload, dict):
        for key in keys:
            if isinstance(payload.get(key), list):
                return [item for item in payload[key] if isinstance(item, dict)]
        for value in payload.values():  # last resort: the only list in there
            if isinstance(value, list) and all(isinstance(v, dict) for v in value):
                return value
    return []


def parse_symbol(raw: dict[str, Any]) -> SymbolRef:
    """PIN AT 09:15 against real `entire graph def --json` output."""
    location = _first(raw, "location", "position", default={})
    if isinstance(location, str) and ":" in location:  # "path/to/file.py:41"
        path, _, line_text = location.rpartition(":")
        location = {"file": path, "line": line_text}
    elif not isinstance(location, dict):
        location = {}

    file = _first(raw, "file", "path", "filename", default=None) or _first(
        location, "file", "path", default="<unknown>"
    )
    line = _first(raw, "line", "start_line", "lineno", default=None) or _first(
        location, "line", "start_line", default=0
    )
    kind_text = str(_first(raw, "kind", "type", "symbol_kind", default="symbol")).lower()

    return SymbolRef(
        file=str(file),
        line=int(line or 0),
        name=str(_first(raw, "name", "symbol", "qualified_name", default="<anonymous>")),
        id=str(_first(raw, "id", "symbol_id", "uid", default="")),
        kind=SymbolKind(kind_text) if kind_text in set(SymbolKind) else SymbolKind.SYMBOL,
    )


def parse_reach(raw: dict[str, Any], *, origin: SymbolRef | None = None) -> Reach:
    """PIN AT 09:15 against real `entire graph impact --json` output."""
    node = _first(raw, "symbol", "target", "node", default=raw)
    symbol = parse_symbol(node if isinstance(node, dict) else raw)

    edges_raw = _first(raw, "edge_kinds", "edges", "relations", "via_edges", default=())
    if isinstance(edges_raw, str):
        edges_raw = [edges_raw]
    edges = tuple(
        EdgeKind(e) if e in set(EdgeKind) else EdgeKind.UNKNOWN
        for e in (str(x).lower().replace("_", "-") for x in edges_raw or ())
    )

    path_raw = _first(raw, "path", "via", "chain", default=())
    via = tuple(parse_symbol(p) for p in path_raw if isinstance(p, dict))

    distance = _first(raw, "distance", "depth", "hops", default=None)
    if distance is None:
        distance = max(len(via) - 1, 1) if via else 1

    return Reach(
        symbol=symbol,
        distance=int(distance),
        origin=origin,
        edge_kinds=edges,
        via=via,
    )


def parse_changed(raw: dict[str, Any]) -> ChangedSymbol:
    """PIN AT 09:15 against real `entire graph diff --json` output."""
    node = _first(raw, "symbol", "node", default=raw)
    change_text = str(_first(raw, "change", "status", "kind", default="modified")).lower()
    change = ChangeKind(change_text) if change_text in set(ChangeKind) else ChangeKind.MODIFIED
    return ChangedSymbol(parse_symbol(node if isinstance(node, dict) else raw), change)


# ---------------------------------------------------------------------------
# default: shell out to the plugin
# ---------------------------------------------------------------------------


class EntireGraphProvider:
    """`entire graph <cmd> --json`, memoized.

    Memoization is not premature: `impact` gets called once per changed symbol
    and the same neighbours come back repeatedly. It is also the cheapest half
    of the answer to a latency curveball — the other half is `config.head`.
    """

    mode = GraphMode.SEMANTIC

    def __init__(self, config: Config) -> None:
        self.config = config
        self._cache: dict[tuple[str, ...], Any] = {}
        self._queries = 0
        self._hits = 0

    # --- plumbing ---------------------------------------------------------

    def _run(self, *args: str) -> Any:
        argv: tuple[str, ...] = (
            self.config.entire_bin,
            "graph",
            *args,
            "--repo",
            str(self.config.repo),
            "--json",
        )
        if self.config.head:
            argv += ("--head",)

        if argv in self._cache:
            self._hits += 1
            return self._cache[argv]

        self._queries += 1
        try:
            proc = subprocess.run(
                argv,
                capture_output=True,
                text=True,
                timeout=self.config.timeout_s,
                check=False,
            )
        except FileNotFoundError as exc:
            raise GraphUnavailable(f"{self.config.entire_bin} not on PATH") from exc
        except subprocess.TimeoutExpired as exc:
            raise GraphError(f"timed out after {self.config.timeout_s}s: {' '.join(args)}") from exc

        if proc.returncode != 0:
            raise GraphError(f"`{' '.join(argv)}` exited {proc.returncode}: {proc.stderr.strip()}")

        try:
            payload = json.loads(proc.stdout or "null")
        except json.JSONDecodeError as exc:
            raise GraphError(f"non-JSON output from `{' '.join(args)}`: {proc.stdout[:200]}") from exc

        self._cache[argv] = payload
        return payload

    def query_stats(self) -> tuple[int, int]:
        return self._queries, self._hits

    # --- questions --------------------------------------------------------

    def capabilities(self) -> Capabilities:
        payload = self._run("capabilities")
        languages = _first(payload or {}, "languages", "semantic_languages", default=[])
        names = frozenset(
            str(_first(lang, "extension", "ext", "name", default="")).lstrip(".")
            if isinstance(lang, dict)
            else str(lang).lstrip(".")
            for lang in languages
        )
        mode = GraphMode.SEMANTIC if names else GraphMode.INVENTORY
        return Capabilities(mode=mode, languages=names - {""}, raw=payload if isinstance(payload, dict) else None)

    def changed_symbols(self) -> list[ChangedSymbol]:
        return [parse_changed(item) for item in _items(self._run("diff"), "changed", "symbols", "results")]

    def impact(self, symbol: SymbolRef, *, depth: int) -> list[Reach]:
        payload = self._run("impact", "--symbol", symbol.name)
        reaches = [
            parse_reach(item, origin=symbol)
            for item in _items(payload, "impact", "impacted", "symbols", "results")
        ]
        capped = [r for r in reaches if r.distance <= depth]
        return capped[: self.config.max_symbols_per_query]

    def neighbors(self, symbol: SymbolRef) -> list[Reach]:
        payload = self._run("neighbors", symbol.name)
        return [
            parse_reach(item, origin=symbol)
            for item in _items(payload, "neighbors", "edges", "results")
        ]

    def symbols(self, *, path_prefix: str | None = None) -> list[SymbolRef]:
        found = [parse_symbol(item) for item in _items(self._run("symbols"), "symbols", "results")]
        if path_prefix:
            found = [s for s in found if s.file.startswith(path_prefix)]
        return found

    def define(self, name: str) -> SymbolRef | None:
        try:
            payload = self._run("def", name)
        except GraphError:
            return None  # unresolvable name is an overclaim, not a failure
        items = _items(payload, "definitions", "symbols", "results")
        if items:
            return parse_symbol(items[0])
        return parse_symbol(payload) if isinstance(payload, dict) and payload else None


# ---------------------------------------------------------------------------
# curveball seam: "your reviewer has no working tree"
# ---------------------------------------------------------------------------


class SnapshotGraphProvider:
    """Serves the same six questions from an `entire graph snapshot` export.

    Deliberately a skeleton. If noon doesn't ask for it, it costs nothing; if it
    does, the shape of the work is already decided and the core never changes.
    Build order when it lands: _index() first, then symbols/define, then
    neighbors, then impact as a BFS over the adjacency map.
    """

    mode = GraphMode.SNAPSHOT

    def __init__(self, config: Config, snapshot: Path | None = None) -> None:
        self.config = config
        self.path = snapshot or config.snapshot
        if self.path is None:
            raise GraphUnavailable("SnapshotGraphProvider needs config.snapshot")
        self._raw: dict[str, Any] | None = None
        self._by_name: dict[str, SymbolRef] = {}
        self._edges: dict[str, list[tuple[str, EdgeKind]]] = {}

    def _index(self) -> None:
        if self._raw is not None:
            return
        self._raw = json.loads(Path(self.path).read_text())
        for item in _items(self._raw, "symbols", "nodes"):
            symbol = parse_symbol(item)
            self._by_name[symbol.name] = symbol
        # TODO(noon): build self._edges from _items(self._raw, "edges") so
        # impact() is a BFS with the same depth cap as EntireGraphProvider.

    def capabilities(self) -> Capabilities:
        self._index()
        return Capabilities(mode=GraphMode.SNAPSHOT, raw=self._raw)

    def changed_symbols(self) -> list[ChangedSymbol]:
        # A snapshot has no working tree to diff. The caller supplies the
        # changed set from the checkpoint's files-touched instead.
        raise GraphUnavailable("snapshot has no working tree; use checkpoint files-touched")

    def impact(self, symbol: SymbolRef, *, depth: int) -> list[Reach]:
        raise NotImplementedError("noon seam: BFS over self._edges")

    def neighbors(self, symbol: SymbolRef) -> list[Reach]:
        raise NotImplementedError("noon seam: one hop over self._edges")

    def symbols(self, *, path_prefix: str | None = None) -> list[SymbolRef]:
        self._index()
        found = list(self._by_name.values())
        return [s for s in found if s.file.startswith(path_prefix)] if path_prefix else found

    def define(self, name: str) -> SymbolRef | None:
        self._index()
        return self._by_name.get(name)

    def query_stats(self) -> tuple[int, int]:
        return (1, 0)


# ---------------------------------------------------------------------------
# curveball seam: "run it on a language the graph doesn't parse"
# ---------------------------------------------------------------------------


class DegradedGraphProvider:
    """No call analysis. File-level changes only, and honest about it.

    This one is fully implemented rather than stubbed, because a report that
    says "inventory only, here is what changed, reach unresolved" beats a crash
    in front of judges — and `Report.is_degraded` already routes the wording.
    """

    mode = GraphMode.UNAVAILABLE

    def __init__(self, config: Config, reason: str = "graph unavailable") -> None:
        self.config = config
        self.reason = reason

    def _git(self, *args: str) -> str:
        proc = subprocess.run(
            ("git", "-C", str(self.config.repo), *args),
            capture_output=True, text=True, timeout=self.config.timeout_s, check=False,
        )
        return proc.stdout if proc.returncode == 0 else ""

    def capabilities(self) -> Capabilities:
        return Capabilities(mode=GraphMode.UNAVAILABLE)

    def changed_symbols(self) -> list[ChangedSymbol]:
        ref = "HEAD~1" if self.config.head else "HEAD"
        paths = [p for p in self._git("diff", "--name-only", ref).splitlines() if p.strip()]
        return [
            ChangedSymbol(SymbolRef(file=path, line=0, name=path, kind=SymbolKind.FILE))
            for path in paths
        ]

    def impact(self, symbol: SymbolRef, *, depth: int) -> list[Reach]:
        return []

    def neighbors(self, symbol: SymbolRef) -> list[Reach]:
        return []

    def symbols(self, *, path_prefix: str | None = None) -> list[SymbolRef]:
        paths = [p for p in self._git("ls-files").splitlines() if p.strip()]
        if path_prefix:
            paths = [p for p in paths if p.startswith(path_prefix)]
        return [SymbolRef(file=p, line=0, name=p, kind=SymbolKind.FILE) for p in paths]

    def define(self, name: str) -> SymbolRef | None:
        return None

    def query_stats(self) -> tuple[int, int]:
        return (0, 0)


# ---------------------------------------------------------------------------
# the swap
# ---------------------------------------------------------------------------


def select_provider(config: Config) -> tuple[GraphProvider, str | None]:
    """Pick a provider and say why, if it isn't the good one.

    At 12:00 this function is where most constraints land. Returning the reason
    alongside the provider means the report can be honest without the core
    knowing anything about why.
    """
    if config.snapshot is not None:
        return SnapshotGraphProvider(config), None

    provider = EntireGraphProvider(config)
    try:
        caps = provider.capabilities()
    except GraphError as exc:
        return DegradedGraphProvider(config, str(exc)), f"falling back to git: {exc}"

    if not caps.semantic:
        return DegradedGraphProvider(config, "inventory-only"), (
            "graph reports inventory-only for this repo; reach is not resolved"
        )
    provider.mode = caps.mode
    return provider, None

