"""Lane B: `entire checkpoint explain` -> Claim.

Deterministic and model-free by construction. Not because it's simpler — a
model would extract claims better — but because "no LLM calls" is the single
most likely Noon Curveball for a tool whose whole pitch is trustworthy review.
If we can't call a model at 12:30 and this module needed one, we lose the
product. If it never needed one, the curveball costs us nothing.

Entry from either side of the link: a checkpoint ULID, or a commit SHA whose
message carries the `Entire-Checkpoint:` trailer.

WARNING — as in graph.py, the metadata field names below are written against
the documented shape, not against output anyone has seen. PIN AT 09:15.
"""

from __future__ import annotations

import json
import re
import subprocess
from dataclasses import dataclass, field
from datetime import datetime
from enum import StrEnum
from typing import Any, Iterable, Protocol, Sequence

from .config import Config
from .graph import GraphError, GraphProvider, GraphUnavailable, _first, _items
from .report import Claim, ClaimSource, SymbolRef


class CheckpointError(RuntimeError):
    """Could not read a checkpoint."""


# ---------------------------------------------------------------------------
# identity
# ---------------------------------------------------------------------------

ULID_RE = re.compile(r"^[0-9A-HJKMNP-TV-Z]{26}$", re.IGNORECASE)  # Crockford base32
LEGACY_ID_RE = re.compile(r"^[0-9a-f]{12}$", re.IGNORECASE)
TRAILER_RE = re.compile(r"^Entire-Checkpoint:\s*(\S+)\s*$", re.MULTILINE)


def looks_like_checkpoint_id(ref: str) -> bool:
    return bool(ULID_RE.match(ref) or LEGACY_ID_RE.match(ref))


@dataclass(frozen=True, slots=True)
class Checkpoint:
    """What the agent left behind. `summary` is what a reviewer would read."""

    id: str
    summary: str = ""
    commit_sha: str | None = None
    files: tuple[str, ...] = ()
    prompts: tuple[str, ...] = ()
    transcript: str = ""
    created_at: datetime | None = None
    raw: dict[str, Any] = field(default_factory=dict, repr=False)

    @classmethod
    def from_raw(cls, raw: dict[str, Any], *, checkpoint_id: str | None = None) -> Checkpoint:
        """PIN AT 09:15 against real `entire checkpoint explain --json` output."""
        files_raw = _first(raw, "files", "files_touched", "changed_files", "paths", default=())
        files = tuple(
            str(_first(f, "path", "file", "name", default="")) if isinstance(f, dict) else str(f)
            for f in files_raw or ()
        )

        prompts_raw = _first(raw, "prompts", "user_prompts", "instructions", default=())
        prompts = tuple(
            str(_first(p, "text", "content", "prompt", default="")) if isinstance(p, dict) else str(p)
            for p in prompts_raw or ()
        )

        created = _first(raw, "created_at", "timestamp", "time")
        try:
            created_at = datetime.fromisoformat(str(created)) if created else None
        except ValueError:
            created_at = None

        return cls(
            id=str(_first(raw, "id", "checkpoint_id", "ulid", default=checkpoint_id or "")),
            summary=str(_first(raw, "summary", "description", "title", "message", default="")),
            commit_sha=_first(raw, "commit", "commit_sha", "sha"),
            files=tuple(f for f in files if f),
            prompts=tuple(p for p in prompts if p),
            transcript=_transcript_text(raw),
            created_at=created_at,
            raw=raw,
        )


def _transcript_text(raw: dict[str, Any]) -> str:
    """Flatten whatever transcript shape we get into searchable text."""
    transcript = _first(raw, "transcript", "messages", "turns", "session", default=None)
    if isinstance(transcript, str):
        return transcript
    parts: list[str] = []
    for item in _items(transcript, "messages", "turns", "entries"):
        text = _first(item, "text", "content", "message", "body", default="")
        parts.append(text if isinstance(text, str) else json.dumps(text))
    return "\n".join(p for p in parts if p)


# ---------------------------------------------------------------------------
# sources
# ---------------------------------------------------------------------------


class CheckpointSource(Protocol):
    def resolve(self, ref: str) -> str:
        """Turn a ULID, a commit SHA, or HEAD into a checkpoint id."""

    def explain(self, checkpoint_id: str) -> Checkpoint: ...

    def recent(self, limit: int = 20) -> list[Checkpoint]: ...


class EntireCheckpointSource:
    """`entire checkpoint ...`, with a git-trailer path for commit refs."""

    def __init__(self, config: Config) -> None:
        self.config = config

    def _entire(self, *args: str) -> Any:
        argv = (self.config.entire_bin, "checkpoint", *args, "--json")
        try:
            proc = subprocess.run(
                argv, capture_output=True, text=True,
                timeout=self.config.timeout_s, check=False, cwd=self.config.repo,
            )
        except FileNotFoundError as exc:
            raise CheckpointError(f"{self.config.entire_bin} not on PATH") from exc
        except subprocess.TimeoutExpired as exc:
            raise CheckpointError(f"timed out: {' '.join(args)}") from exc
        if proc.returncode != 0:
            raise CheckpointError(f"`{' '.join(argv)}` exited {proc.returncode}: {proc.stderr.strip()}")
        try:
            return json.loads(proc.stdout or "null")
        except json.JSONDecodeError as exc:
            raise CheckpointError(f"non-JSON from `{' '.join(args)}`") from exc

    def _git(self, *args: str) -> str:
        proc = subprocess.run(
            ("git", "-C", str(self.config.repo), *args),
            capture_output=True, text=True, timeout=self.config.timeout_s, check=False,
        )
        return proc.stdout if proc.returncode == 0 else ""

    def resolve(self, ref: str) -> str:
        if looks_like_checkpoint_id(ref):
            return ref
        # A commit: the CLI writes an `Entire-Checkpoint:` trailer on linked commits.
        message = self._git("log", "-1", "--format=%B", ref)
        if match := TRAILER_RE.search(message):
            return match.group(1)
        # Last resort: newest checkpoint on the branch.
        if recent := self.recent(limit=1):
            return recent[0].id
        raise CheckpointError(f"no checkpoint found for {ref!r}")

    def explain(self, checkpoint_id: str) -> Checkpoint:
        payload = self._entire("explain", checkpoint_id)
        if not isinstance(payload, dict):
            items = _items(payload, "checkpoints", "results")
            payload = items[0] if items else {}
        return Checkpoint.from_raw(payload, checkpoint_id=checkpoint_id)

    def recent(self, limit: int = 20) -> list[Checkpoint]:
        payload = self._entire("list")
        items = _items(payload, "checkpoints", "results", "items")
        return [Checkpoint.from_raw(item) for item in items[:limit]]


class GitRefCheckpointSource:
    """Read checkpoints straight out of `refs/entire/checkpoints/...`.

    Checkpoint refs point at commits holding `metadata.json`. This is the
    fallback when the CLI is missing, wedged, or a different version than the
    one we tested at 09:15 — and it is why the demo can't be broken by a plugin
    upgrade landing mid-morning.
    """

    def __init__(self, config: Config) -> None:
        self.config = config

    def _git(self, *args: str) -> str:
        proc = subprocess.run(
            ("git", "-C", str(self.config.repo), *args),
            capture_output=True, text=True, timeout=self.config.timeout_s, check=False,
        )
        return proc.stdout if proc.returncode == 0 else ""

    def _refs(self) -> list[tuple[str, str]]:
        out = self._git("for-each-ref", "--format=%(refname) %(objectname)", "refs/entire/checkpoints")
        refs: list[tuple[str, str]] = []
        for line in out.splitlines():
            refname, _, sha = line.strip().partition(" ")
            if refname and sha:
                refs.append((refname, sha))
        return refs

    def resolve(self, ref: str) -> str:
        if looks_like_checkpoint_id(ref):
            return ref
        if match := TRAILER_RE.search(self._git("log", "-1", "--format=%B", ref)):
            return match.group(1)
        refs = self._refs()
        if refs:
            return refs[-1][0].rsplit("/", 1)[-1]
        raise CheckpointError("no checkpoint refs in this repo")

    def explain(self, checkpoint_id: str) -> Checkpoint:
        for refname, _ in self._refs():
            if refname.rsplit("/", 1)[-1] == checkpoint_id:
                blob = self._git("show", f"{refname}:metadata.json")
                if not blob:
                    break
                return Checkpoint.from_raw(json.loads(blob), checkpoint_id=checkpoint_id)
        raise CheckpointError(f"no ref for checkpoint {checkpoint_id}")

    def recent(self, limit: int = 20) -> list[Checkpoint]:
        out: list[Checkpoint] = []
        for refname, _ in self._refs()[-limit:]:
            try:
                out.append(self.explain(refname.rsplit("/", 1)[-1]))
            except (CheckpointError, json.JSONDecodeError):
                continue
        return out


class FixtureCheckpointSource:
    """A checkpoint frozen to a JSON file. The offline demo, and lane C's unblock."""

    def __init__(self, path: str) -> None:
        self.payload = json.loads(open(path).read())

    def resolve(self, ref: str) -> str:
        return str(_first(self.payload, "id", "checkpoint_id", default=ref))

    def explain(self, checkpoint_id: str) -> Checkpoint:
        return Checkpoint.from_raw(self.payload, checkpoint_id=checkpoint_id)

    def recent(self, limit: int = 20) -> list[Checkpoint]:
        return [self.explain(self.resolve(""))]


def select_source(config: Config) -> CheckpointSource:
    source = EntireCheckpointSource(config)
    try:
        source.recent(limit=1)
        return source
    except CheckpointError:
        return GitRefCheckpointSource(config)


# ---------------------------------------------------------------------------
# candidate extraction — structural only, no NLP, no model
# ---------------------------------------------------------------------------


class Strength(StrEnum):
    """How sure we are that a token was meant as a code identifier.

    STRONG survives non-resolution and becomes an overclaim: the agent named
    something specific that isn't in the graph. WEAK is dropped silently when
    it doesn't resolve, because "middleware" in a sentence is a word, not a
    claim, and a false overclaim is worse than a missed one.
    """

    STRONG = "strong"
    WEAK = "weak"


BACKTICK_RE = re.compile(r"`([^`\n]{1,120})`")
PATH_RE = re.compile(r"\b((?:[\w.-]+/)+[\w.-]+\.\w{1,6})\b")
CALL_RE = re.compile(r"\b([A-Za-z_][\w.]*)\s*\(")
DOTTED_RE = re.compile(r"\b([A-Za-z_]\w*(?:\.[A-Za-z_]\w*)+)\b")
SNAKE_RE = re.compile(r"\b([a-z][a-z0-9]*(?:_[a-z0-9]+)+)\b")
CAMEL_RE = re.compile(r"\b((?:[a-z]+(?:[A-Z][a-z0-9]*)+)|(?:[A-Z][a-z0-9]+(?:[A-Z][a-z0-9]*)+))\b")
WORD_RE = re.compile(r"\b([a-z][a-z0-9]{2,})\b")

# Words that pass the weak filter but never mean a symbol. Deliberately short:
# weak candidates must resolve against the graph anyway, so this list only has
# to stop the ones that would collide with a real symbol name.
STOPWORDS = frozenset("""
add added also and any are but change changed changes code file files fix fixed for
from function functions has have implementation implemented into logic method methods
new none nothing now only other others refactor refactored remove removed rename renamed
should side small some test tests that the then this update updated use used using was
were which while with without work working
""".split())


@dataclass(frozen=True, slots=True)
class Candidate:
    name: str
    strength: Strength
    where: str  # "summary" | "prompt" | "transcript"


def candidates(text: str, where: str) -> list[Candidate]:
    """Every token in `text` that could plausibly be a symbol name."""
    found: dict[str, Candidate] = {}

    def add(name: str, strength: Strength) -> None:
        name = name.strip().strip("`'\"(),.;:")
        if not name or name.lower() in STOPWORDS:
            return
        existing = found.get(name)
        if existing is None or (existing.strength is Strength.WEAK and strength is Strength.STRONG):
            found[name] = Candidate(name, strength, where)

    for pattern in (BACKTICK_RE, PATH_RE, CALL_RE, DOTTED_RE, SNAKE_RE, CAMEL_RE):
        for match in pattern.finditer(text):
            add(match.group(1), Strength.STRONG)
    for match in WORD_RE.finditer(text):
        add(match.group(1), Strength.WEAK)

    return list(found.values())


SCOPE_ASSERTION_RE = re.compile(
    r"("
    r"nothing (?:else|further) (?:is |was |should be )?(?:affected|impacted|changed|touched)"
    r"|no (?:other|further) (?:files?|callers?|changes?|modules?|tests?)"
    r"|(?:does|do|did|should) not (?:affect|impact|change|touch|break)[^.\n]*"
    r"|(?:this|the change|it) is (?:fully )?(?:backwards[- ]compatible|isolated|self[- ]contained)"
    r"|no (?:behaviou?ral|functional) changes?"
    r")",
    re.IGNORECASE,
)


def find_scope_assertions(text: str) -> tuple[str, ...]:
    """The sentences that make the demo land.

    Deliberately NOT a new field on `Claim` — the contract is frozen and
    `Claim.summary` already carries the text. Renderers call this to highlight
    the assertion the graph is about to contradict.
    """
    return tuple(dict.fromkeys(m.group(1).strip() for m in SCOPE_ASSERTION_RE.finditer(text)))


# ---------------------------------------------------------------------------
# resolution
# ---------------------------------------------------------------------------


class SymbolIndex:
    """One `graph.symbols()` call, three lookup strategies.

    Built once rather than calling `graph.define()` per candidate — define is a
    subprocess each time, and a wordy summary yields dozens of candidates.
    define() stays as the fallback for names the table doesn't hold.
    """

    def __init__(self, symbols: Iterable[SymbolRef]) -> None:
        self.by_name: dict[str, SymbolRef] = {}
        self.by_lower: dict[str, SymbolRef] = {}
        self.by_tail: dict[str, SymbolRef] = {}
        self.by_file: dict[str, SymbolRef] = {}
        for symbol in symbols:
            self.by_name.setdefault(symbol.name, symbol)
            self.by_lower.setdefault(symbol.name.lower(), symbol)
            self.by_tail.setdefault(symbol.name.rsplit(".", 1)[-1], symbol)
            self.by_file.setdefault(symbol.file, symbol)

    def lookup(self, name: str) -> SymbolRef | None:
        return (
            self.by_name.get(name)
            or self.by_tail.get(name.rsplit(".", 1)[-1])
            or self.by_lower.get(name.lower())
            or self.by_file.get(name)
        )


# ---------------------------------------------------------------------------
# the extractor
# ---------------------------------------------------------------------------


def extract_claim(
    checkpoint: Checkpoint,
    graph: GraphProvider,
    config: Config,
    *,
    include_transcript: bool = False,
) -> Claim:
    """What the agent said it did, as a set of real symbols.

    On `include_transcript`: off by default, and the default is the honest one
    even though it is also the one that finds more. A claim set built from the
    whole transcript is larger, which shrinks `silent` — every symbol the agent
    mentioned in passing at 10:04 counts as disclosed. But a reviewer reads the
    summary, not 40k tokens of session log, so the summary is the claim being
    made. Run with `--strict-claims` to scan the transcript and show the finding
    survives the stricter reading; if a judge asks whether we are grading on a
    curve, that flag is the answer.
    """
    texts: list[tuple[str, str]] = [("summary", checkpoint.summary)]
    texts += [("prompt", p) for p in checkpoint.prompts]
    if include_transcript and checkpoint.transcript:
        texts.append(("transcript", checkpoint.transcript))

    found: dict[str, Candidate] = {}
    for where, text in texts:
        for candidate in candidates(text, where):
            existing = found.get(candidate.name)
            if existing is None or (
                existing.strength is Strength.WEAK and candidate.strength is Strength.STRONG
            ):
                found[candidate.name] = candidate

    # Files touched are structural and always trustworthy.
    files = tuple(dict.fromkeys(checkpoint.files))
    sources: list[ClaimSource] = [ClaimSource.FILES_TOUCHED]

    try:
        index = SymbolIndex(graph.symbols())
    except (GraphError, GraphUnavailable):
        # Degraded: no symbol table, so no name resolution and — importantly —
        # no overclaims, because we cannot tell a missing symbol from a missing
        # graph. Say so rather than reporting confidently on nothing.
        return Claim(
            summary=checkpoint.summary,
            files=files,
            sources=(ClaimSource.STRUCTURAL,),
        )

    symbols: list[SymbolRef] = []
    unresolved: list[str] = []
    for candidate in found.values():
        symbol = index.lookup(candidate.name)
        if symbol is None and candidate.strength is Strength.STRONG:
            symbol = graph.define(candidate.name)  # one subprocess, strong names only
        if symbol is not None:
            symbols.append(symbol)
            if candidate.where == "summary":
                sources.append(ClaimSource.SUMMARY)
            elif candidate.where == "transcript":
                sources.append(ClaimSource.TRANSCRIPT)
        elif candidate.strength is Strength.STRONG:
            unresolved.append(candidate.name)

    # Symbols defined in the files the agent actually touched are claimed too —
    # you cannot edit a file and say you didn't touch what's in it.
    for path in files:
        for symbol in index.by_file.values():
            if symbol.file == path:
                symbols.append(symbol)

    return Claim(
        summary=checkpoint.summary,
        symbols=tuple(dict.fromkeys(symbols)),
        files=files,
        unresolved=tuple(dict.fromkeys(unresolved)),
        sources=tuple(dict.fromkeys(sources)),
    )


def load_claim(
    ref: str,
    graph: GraphProvider,
    config: Config,
    *,
    source: CheckpointSource | None = None,
    include_transcript: bool = False,
) -> tuple[Checkpoint, Claim]:
    """ref -> checkpoint -> claim. The whole of lane B in one call."""
    src = source or select_source(config)
    checkpoint = src.explain(src.resolve(ref))
    return checkpoint, extract_claim(checkpoint, graph, config, include_transcript=include_transcript)

