"""The `entire blastradius` verb.

    entire blastradius                    # HEAD's checkpoint, human output
    entire blastradius <ULID>             # a specific checkpoint
    entire blastradius --last 5           # the branch, as a ReportSet
    entire blastradius -f ci              # annotations + exit code
    entire blastradius --replay demo.json # no repo, no CLI, no network

Exit codes are the CI contract: 0 clean, 1 findings, 2 could not analyse.

Nothing in here decides anything. It parses flags into a Config, picks a
source and a provider, calls analyze(), and prints. Every branch that could
fail prints one line to stderr and exits 2 — a traceback in front of judges
reads as a broken tool even when the finding behind it was correct.
"""

from __future__ import annotations

import argparse
import json
import sys
from dataclasses import replace
from pathlib import Path

from .checkpoints import (
    Checkpoint,
    CheckpointError,
    FixtureCheckpointSource,
    extract_claim,
    select_source,
)
from .config import Config
from .core import analyze
from .graph import GraphError, GraphProvider, GraphUnavailable, select_provider
from .render import RENDERERS, RenderOptions, render
from .report import ChangedSymbol, Report, ReportSet

__version__ = "0.1.0"
MIN_PYTHON = (3, 12)


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="entire blastradius",
        description="What the agent said it changed, checked against the graph.",
    )
    parser.add_argument(
        "ref",
        nargs="?",
        default="HEAD",
        help="checkpoint ULID, commit SHA, or HEAD (default: HEAD)",
    )
    parser.add_argument("-f", "--format", default="text", choices=sorted(RENDERERS))
    parser.add_argument("--repo", type=Path, default=Path("."))

    scope = parser.add_argument_group("scope")
    scope.add_argument("--last", type=int, metavar="N", help="analyse the N most recent checkpoints")
    scope.add_argument(
        "--strict-claims",
        action="store_true",
        help="credit the agent for symbols named anywhere in the transcript, "
        "not just the summary (finds less; proves the finding is real)",
    )
    scope.add_argument("--depth", type=int, help="max hops from a changed symbol")
    scope.add_argument(
        "--threshold", type=int, metavar="N", help="untested reach that trips a non-zero exit"
    )

    graph = parser.add_argument_group("graph")
    graph.add_argument("--head", action="store_true", help="query the committed tree (faster, cached)")
    graph.add_argument("--snapshot", type=Path, help="use an `entire graph snapshot` export")

    offline = parser.add_argument_group("offline")
    offline.add_argument("--fixture", type=Path, help="read the checkpoint from a JSON file")
    offline.add_argument("--replay", type=Path, help="render a saved report; touches nothing")
    offline.add_argument("--save", type=Path, help="write the report JSON (makes a --replay file)")

    out = parser.add_argument_group("output")
    out.add_argument("--list", action="store_true", help="list recent checkpoints and exit")
    out.add_argument("-v", "--verbose", action="store_true", help="also show confirmed reach")
    out.add_argument("--max-findings", type=int, default=20)
    colour = out.add_mutually_exclusive_group()
    colour.add_argument("--color", dest="color", action="store_true", default=None)
    colour.add_argument("--no-color", dest="color", action="store_false")

    parser.add_argument("--version", action="version", version=f"blastradius {__version__}")
    return parser


def config_from(args: argparse.Namespace) -> Config:
    overrides: dict[str, object] = {"repo": args.repo, "head": args.head}
    if args.snapshot:
        overrides["snapshot"] = args.snapshot
    if args.depth:
        overrides["depth_cap"] = args.depth
    if args.threshold is not None:
        overrides["untested_threshold"] = args.threshold
    return replace(Config.from_env(), **overrides)  # type: ignore[arg-type]


def changed_from_files(checkpoint: Checkpoint, graph: GraphProvider) -> list[ChangedSymbol]:
    """Historical checkpoints can't be diffed against the working tree.

    For `--last`, derive the changed set from the checkpoint's own files-touched
    instead. Less precise than `entire graph diff`, and honest about which
    checkpoint each finding belongs to.
    """
    touched = set(checkpoint.files)
    return [ChangedSymbol(s) for s in graph.symbols() if s.file in touched]


def die(message: str) -> int:
    print(f"blastradius: {message}", file=sys.stderr)
    return 2


def main(argv: list[str] | None = None) -> int:
    if sys.version_info < MIN_PYTHON:
        return die(
            f"needs Python {'.'.join(map(str, MIN_PYTHON))}+, running "
            f"{sys.version_info.major}.{sys.version_info.minor} "
            "(set BLASTRADIUS_PYTHON to a newer interpreter)"
        )

    args = build_parser().parse_args(argv)
    opts = RenderOptions.detect(
        force_color=args.color, show_confirmed=args.verbose, max_findings=args.max_findings
    )

    # --- offline paths, which need neither a repo nor the CLI ---------------
    if args.replay:
        try:
            payload = json.loads(args.replay.read_text())
        except (OSError, json.JSONDecodeError) as exc:
            return die(f"cannot replay {args.replay}: {exc}")
        raw = payload.get("reports", [payload]) if isinstance(payload, dict) else payload
        reports = ReportSet(tuple(Report.from_dict(r) for r in raw))
        print(render(reports, args.format, opts))
        return reports.exit_code()

    config = config_from(args)

    # --- sources ------------------------------------------------------------
    try:
        source = FixtureCheckpointSource(str(args.fixture)) if args.fixture else select_source(config)
    except (CheckpointError, OSError, json.JSONDecodeError) as exc:
        return die(f"no checkpoints available: {exc}")

    if args.list:
        try:
            for checkpoint in source.recent(limit=args.last or 20):
                stamp = checkpoint.created_at.isoformat(timespec="minutes") if checkpoint.created_at else ""
                summary = (checkpoint.summary or "").split("\n")[0][:72]
                print(f"{checkpoint.id}  {stamp:16}  {summary}")
        except CheckpointError as exc:
            return die(str(exc))
        return 0

    # --- graph --------------------------------------------------------------
    try:
        graph, degraded_reason = select_provider(config)
    except GraphUnavailable as exc:
        return die(f"{exc}\nhint: `entire plugin install graph`, then `entire graph version`")

    # --- checkpoints to analyse --------------------------------------------
    try:
        if args.last:
            checkpoints = source.recent(limit=args.last)
        else:
            checkpoints = [source.explain(source.resolve(args.ref))]
    except CheckpointError as exc:
        return die(str(exc))

    if not checkpoints:
        return die("no checkpoints found — is `entire enable` set up in this repo?")

    reports: list[Report] = []
    for checkpoint in checkpoints:
        try:
            claim = extract_claim(
                checkpoint, graph, config, include_transcript=args.strict_claims
            )
            changed = changed_from_files(checkpoint, graph) if args.last else None
            reports.append(
                analyze(
                    checkpoint.id,
                    claim,
                    graph,
                    config,
                    commit_sha=checkpoint.commit_sha,
                    degraded_reason=degraded_reason,
                    changed=changed,
                )
            )
        except GraphError as exc:
            return die(f"graph query failed for {checkpoint.id}: {exc}")

    report_set = ReportSet(tuple(reports))

    if args.save:
        try:
            args.save.write_text(report_set.to_json())
        except OSError as exc:
            return die(f"cannot write {args.save}: {exc}")

    print(render(report_set, args.format, opts))
    return report_set.exit_code(config.untested_threshold)


if __name__ == "__main__":
    sys.exit(main())

