"""Fixtures for the two suites that matter.

`bucket()` needs nothing but data. `extract_claim()` needs a graph, so there is
one fake here — configurable, no subprocess, no `entire` binary. If a test in
this directory ever shells out, it is in the wrong directory.
"""

from __future__ import annotations

import sys
from pathlib import Path

import pytest

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from blastradius.checkpoints import Checkpoint  # noqa: E402
from blastradius.config import Config  # noqa: E402
from blastradius.graph import GraphUnavailable  # noqa: E402
from blastradius.report import (  # noqa: E402
    EdgeKind,
    GraphMode,
    Reach,
    SymbolKind,
    SymbolRef,
)

# --- the demo repo, as the graph sees it ------------------------------------

MW = SymbolRef("app/auth/middleware.py", 41, "verify_token", kind=SymbolKind.FUNCTION)
DEP = SymbolRef("app/api/deps.py", 18, "current_user", kind=SymbolKind.FUNCTION)
SVC = SymbolRef("app/services/billing_service.py", 55, "charge_customer", kind=SymbolKind.METHOD)
ROUTE = SymbolRef("app/api/routes/billing.py", 92, "post_charge", kind=SymbolKind.ROUTE)
TEST = SymbolRef("tests/unit/test_deps.py", 12, "test_current_user", kind=SymbolKind.FUNCTION)
HELPER = SymbolRef("app/auth/middleware.py", 12, "claims", kind=SymbolKind.FUNCTION)

ALL_SYMBOLS = [MW, DEP, SVC, ROUTE, TEST, HELPER]


class FakeGraph:
    """Configurable stand-in for `entire graph`.

    Every knob exists because a test needs it: `broken` for the degraded path,
    `definitions` for the `define()` fallback, `impact_map` for reach.
    """

    def __init__(
        self,
        symbols: list[SymbolRef] | None = None,
        impact_map: dict[str, list[Reach]] | None = None,
        definitions: dict[str, SymbolRef] | None = None,
        *,
        broken: bool = False,
        mode: GraphMode = GraphMode.SEMANTIC,
    ) -> None:
        self._symbols = ALL_SYMBOLS if symbols is None else symbols
        self._impact = impact_map or {}
        self._definitions = definitions or {}
        self.broken = broken
        self.mode = mode
        self.define_calls: list[str] = []

    def capabilities(self):  # pragma: no cover - unused by these suites
        raise NotImplementedError

    def changed_symbols(self):
        return []

    def impact(self, symbol, *, depth):
        return [r for r in self._impact.get(symbol.name, []) if r.distance <= depth]

    def neighbors(self, symbol):
        return [Reach(DEP, 1, origin=symbol)] if symbol == TEST else []

    def symbols(self, *, path_prefix=None):
        if self.broken:
            raise GraphUnavailable("no graph in this repo")
        found = self._symbols
        return [s for s in found if s.file.startswith(path_prefix)] if path_prefix else list(found)

    def define(self, name):
        self.define_calls.append(name)
        return self._definitions.get(name)

    def query_stats(self):
        return (len(self._impact), 0)


