"""Checkpoint sources and `Checkpoint.from_raw`.

Same caveat as test_graph.py: these payloads are plausible, not real. They pin
tolerance and the failure modes, not correctness. Paste real
`entire checkpoint explain --json` output into
`test_real_checkpoint_output_pins_from_raw` at 09:15.

The failure modes are the point. A source that raises `CheckpointError` gets a
one-line message and exit 2 from __main__; a source that raises anything else
puts a traceback on the projector.
"""

from __future__ import annotations

import json
import subprocess

import pytest

from blastradius import checkpoints as cp_module
from blastradius.checkpoints import (
    Checkpoint,
    CheckpointError,
    EntireCheckpointSource,
