ULID = "REDACTED"
OTHER_ULID = "REDACTED"


# ---------------------------------------------------------------------------
# subprocess stub, routed by argv[0]
# ---------------------------------------------------------------------------


class FakeProc:
    def __init__(self, stdout: str = "", returncode: int = 0, stderr: str = "") -> None:
        self.stdout, self.returncode, self.stderr = stdout, returncode, stderr


def stub_run(monkeypatch, *, entire=None, git=None):
    """`entire` may be a payload, a FakeProc, an Exception, or a callable.

    `git` may be a callable taking the args after `-C <repo>`, or a dict keyed
    on the git subcommand. Anything unrouted returns empty output.
    """
    calls: list[list[str]] = []

    def fake(argv, **kwargs):
        argv = list(argv)
        calls.append(argv)

        if argv and argv[0] == "git":
            args = argv[3:]  # skip git -C <repo>
            if callable(git):
                return FakeProc(git(args))
            if isinstance(git, dict):
                return FakeProc(git.get(args[0], "") if args else "")
            return FakeProc("")

        if isinstance(entire, BaseException):
            raise entire
        if isinstance(entire, FakeProc):
            return entire
        if callable(entire):
            return entire(argv)
        return FakeProc(json.dumps(entire))

    monkeypatch.setattr(cp_module.subprocess, "run", fake)
    return calls


