def refs_output(*ids: str) -> str:
    return "\n".join(f"refs/entire/checkpoints/ab/{i} {'0' * 40}" for i in ids) + "\n"


def git_repo(*, refs: str = "", metadata: dict | None = None, log: str = ""):
    def handler(args):
        if args[0] == "for-each-ref":
            return refs
        if args[0] == "show":
            return json.dumps(metadata) if metadata is not None else ""
        if args[0] == "log":
            return log
        return ""

    return handler


def test_refs_are_listed_and_resolved(monkeypatch):
    stub_run(monkeypatch, git=git_repo(refs=refs_output(OTHER_ULID, ULID)))

    assert GitRefCheckpointSource(Config()).resolve("HEAD") == ULID


def test_a_ref_backed_checkpoint_is_read_from_metadata_json(monkeypatch):
    stub_run(
        monkeypatch,
        git=git_repo(refs=refs_output(ULID), metadata={"id": ULID, "summary": "from the ref"}),
    )

    assert GitRefCheckpointSource(Config()).explain(ULID).summary == "from the ref"


def test_an_unknown_id_is_an_error_not_a_crash(monkeypatch):
    stub_run(monkeypatch, git=git_repo(refs=refs_output(ULID)))

    with pytest.raises(CheckpointError, match="no ref"):
        GitRefCheckpointSource(Config()).explain(OTHER_ULID)


