def test_recent_skips_refs_it_cannot_read(monkeypatch):
    """One corrupt ref must not take out the listing."""

    def handler(args):
        if args[0] == "for-each-ref":
            return refs_output(ULID, OTHER_ULID)
        if args[0] == "show":
            return "" if OTHER_ULID in args[1] else json.dumps({"id": ULID})
        return ""

